tool_calls.arguments:
{"command":"kubectl create configmap nginx-config --from-literal=nginx.conf='user nginx;
worker_processes auto;
events {
    worker_connections 1024;
}
http {
    include /etc/nginx/conf.d/*.conf;

    # Configuration for temporary files
    client_body_temp_path /var/cache/nginx/temp;
    client_temp_path /var/cache/nginx/temp;

    # Configuration for PID file
    pid /var/cache/nginx/run/nginx.pid;

    server {
        listen 80;
        location / {
            root /usr/share/nginx/html;
        }
    }
}' --namespace default"}

